  ('medication', 'Current medicines', '1990-06-15', 'MedPlus, Koramangala', 'Dr. N. Raghavan', 0.92, '{"title":"Current medicines","fields":[{"key":"patientName","label":"Patient name","value":"-","confidence":0.98},{"key":"eventDate","label":"Date on the document","value":"1990-06-15","confidence":0.92},{"key":"facility","label":"Pharmacy","value":"MedPlus, Koramangala","confidence":0.92},{"key":"doctor","label":"Doctor","value":"Dr. N. Raghavan","confidence":0.86}],"values":[],"details":{"source":"pharmacy","pharmacy":"MedPlus, Koramangala","prescribedBy":"Dr. N. Raghavan (Endocrinology)","startedOn":"1990-06-15","medicines":[{"name":"Metformin","strength":"500 mg","form":"tablet","dose":"1 tablet","schedule":"1-0-1","timing":"after_food","durationDays":90,"qty":180,"expiry":"1991-12-07"},{"name":"Thyronorm","strength":"50 mcg","form":"tablet","dose":"1 tablet","schedule":"1-0-0","timing":"empty_stomach","durationDays":90,"qty":90,"expiry":"1991-07-20","note":"30 minutes before breakfast"},{"name":"Atorvastatin","strength":"10 mg","form":"tablet","dose":"1 tablet","schedule":"0-0-1","timing":"bedtime","durationDays":90,"qty":90,"expiry":"1992-02-15"}]}}', '[{"kind":"medication","name":"Metformin 500 mg","canonical_name":"metformin","value":null,"value_text":"1-0-1 · Twice a day after food, for 90 days","unit":null,"ref_range":null,"flag":null},{"kind":"medication","name":"Thyronorm 50 mcg","canonical_name":"thyronorm","value":null,"value_text":"1-0-0 · Once a day on an empty stomach, for 90 days","unit":null,"ref_range":null,"flag":null},{"kind":"medication","name":"Atorvastatin 10 mg","canonical_name":"atorvastatin","value":null,"value_text":"0-0-1 · Once a day at bedtime, for 90 days","unit":null,"ref_range":null,"flag":null}]'),
